// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output `generated`, whether decoding is
// currently inside a visible constrained SMILES span, and the active
// constrained prefix `currentConstrainedOut`. Outside a span it generates
// freely, but it watches for an observed opening delimiter "<<" and then
// switches into parser-controlled decoding.
// 
// Inside a constrained span, the strategy chooses among three parser-safe
// actions based on local observations. If the current SMILES prefix is already
// complete, it closes the span. If the parser state is narrow or looks close to
// a dead end, it uses a conservative one-token constrained step with repetition
// penalty. Otherwise it uses adaptive group-aware constrained decoding, so
// caller-supplied token groups can softly bias legal continuations while the
// parser remains the hard validity authority. This tracked state supports valid
// SMILES generation because every committed inside-span token is required to
// preserve parser validity, and completion is closed explicitly.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Unconstrained branch: if EOS is produced we break without changing the
//   constrained state. If a non-EOS token is appended and it is not "<<", we
//   remain outside the span so the implication is vacuous. If the observed
//   token is "<<", we set insideConstrainedOut := true and
//   currentConstrainedOut := [], which is valid by the method precondition
//   parser.IsValidPrefix([]).
// - Close branch: CloseConstrainedSpan exits constrained mode and returns an
//   empty currentConstrainedOut, so !insideConstrainedOut ==> current==[] and
//   the parser_validity implication is vacuous afterward.
// - Repair branch: RollbackConstrainedSuffix returns a repaired constrained
//   suffix that is parser-valid, so keeping insideConstrainedOut := true
//   preserves parser_validity.
// - Conservative/adaptive constrained-step branches: each step helper returns
//   either EOS or a token that preserves parser validity. On EOS we break
//   without changing the stored constrained prefix. On a non-EOS token we call
//   AppendConstrainedToken, which extends generated and currentConstrainedOut
//   consistently with that valid next token, preserving parser validity.
//
// progress:
// - Unconstrained branch: UnconstrainedStep consumes exactly one token-step, so
//   after steps := steps + 1, generated grows by at most one visible token
//   (none on EOS, one otherwise). Hence |generated| <= |generatedPrefix| +
//   steps is preserved.
// - Close branch: CloseConstrainedSpan consumes one token-step and appends at
//   most the visible close delimiter, so visible growth is at most the step
//   increment.
// - Repair branch: RollbackConstrainedSuffix consumes no LM token but may shrink
//   or preserve generated; we still charge one loop step, so the bound remains
//   true because visible length does not increase by more than the accounted
//   budget.
// - Conservative/adaptive constrained-step branches: each helper consumes one
//   token-step. If EOS is returned, generated does not grow; otherwise
//   AppendConstrainedToken appends exactly one visible token. Thus visible
//   growth is at most the consumed token budget, preserving
//   |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 12;
var rollbackLimit: nat := 64;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
    var nextConstrained := eosToken;

    if narrow || validCount <= narrowThreshold {
      nextConstrained := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
    } else {
      nextConstrained := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
      );
    }

    steps := steps + 1;
    if nextConstrained == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, nextConstrained
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

